import type { EconomicSymbol } from '../economy/types.js';
import type { EventTemplate, EventTarget, EventOperation, EventEligibility, FinanceAction } from './types.js';

/** Each row declares a real economic channel. Defaults supply units, never a price shock. */
export interface CatalogRule {
  readonly id: string; readonly target: EventTarget; readonly operation: EventOperation;
  readonly sector: string; readonly condition: string; readonly effect: string;
  readonly sign?: 1 | -1; readonly projectKey?: string; readonly successors?: readonly string[];
  readonly eligibility?: readonly EventEligibility[]; readonly subjects?: readonly EconomicSymbol[];
  readonly financeAction?: FinanceAction; readonly investmentAccounting?: NonNullable<EventTemplate['investmentAccounting']>;
  readonly contractRole?: EventTemplate['contractRole'];
  readonly investmentOwner?: EventTemplate['investmentOwner'];
  readonly investmentPurpose?: EventTemplate['investmentPurpose'];
  readonly mode?: EventTemplate['mode']; readonly magnitude?: EventTemplate['magnitude'];
  readonly duration?: EventTemplate['duration']; readonly unit?: EventTemplate['unit'];
  readonly certainty?: EventTemplate['certainty']; readonly sourceType?: EventTemplate['sourceType'];
  readonly halfLifeTicks?: number; readonly cooldownTicks?: number; readonly publishLagTicks?: number;
}
function r(id: string, target: EventTarget, operation: EventOperation, sector: string, condition: string, effect: string, options: Omit<CatalogRule, 'id' | 'target' | 'operation' | 'sector' | 'condition' | 'effect'> = {}): CatalogRule {
  return { id, target, operation, sector, condition, effect, ...options };
}

